void iriap_get_attribute_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    char *class_name = NULL;
    char *attr_name = NULL;
    int class_len, attr_len;
    struct iriap_object *obj;
    struct iriap_attribute *attr;
    char *value = NULL;

    if (!self || !skb) {
        IRDA_DEBUG(1, "%s, invalid parameters\n", __func__);
        return;
    }

    class_name = skb->data;
    class_len = strlen(class_name);
    if (class_len > IRIA_MAX_CLASS_NAME) {
        IRDA_DEBUG(1, "%s, class name too long\n", __func__);
        iriap_send_error(skb, IRIA_ERROR_INVALID_LENGTH);
        return;
    }

    attr_name = class_name + class_len + 1;
    attr_len = strlen(attr_name);
    if (attr_len > IRIA_MAX_ATTR_NAME) {
        IRDA_DEBUG(1, "%s, attribute name too long\n", __func__);
        iriap_send_error(skb, IRIA_ERROR_INVALID_LENGTH);
        return;
    }

    obj = iriap_find_object_by_class(self, class_name);
    if (!obj) {
        IRDA_DEBUG(1, "%s, object not found\n", __func__);
        iriap_send_error(skb, IRIA_ERROR_NO_SUCH_OBJECT);
        return;
    }

    attr = iriap_find_attribute(obj, attr_name);
    if (!attr) {
        IRDA_DEBUG(1, "%s, attribute not found\n", __func__);
        iriap_send_error(skb, IRIA_ERROR_NO_SUCH_ATTRIBUTE);
        return;
    }

    value = attr->value;
    if (!value) {
        IRDA_DEBUG(1, "%s, attribute value is NULL\n", __func__);
        iriap_send_error(skb, IRIA_ERROR_NO_VALUE);
        return;
    }

    iriap_send_response(skb, IRIA_RSP_SUCCESS, value, strlen(value));
}

void iriap_get_attr_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    char class_name[IRDA_NAME_MAX];
    char attr_name[IRDA_NAME_MAX];
    int class_len, attr_len;
    struct iriap_obj *obj;

    if (!self || !skb)
        return;

    class_len = skb->data[0];
    if (class_len > IRDA_NAME_MAX) {
        iriap_send_error(skb, IRIAPE_INVALID_PARAMETER);
        return;
    }

    attr_len = skb->data[class_len + 1];
    if (attr_len > IRDA_NAME_MAX) {
        iriap_send_error(skb, IRIAPE_INVALID_PARAMETER);
        return;
    }

    skb_pull(skb, 1); /* Skip class name length byte */
    skb_copy_from_linear_data(skb, class_name, class_len);
    class_name[class_len] = '\0';

    skb_pull(skb, 1); /* Skip attribute name length byte */
    skb_copy_from_linear_data(skb, attr_name, attr_len);
    attr_name[attr_len] = '\0';

    obj = iriap_find_object(self, class_name);
    if (!obj) {
        iriap_send_error(skb, IRIAPE_NO_SUCH_OBJECT);
        return;
    }

    if (!obj->get_attribute(obj, attr_name)) {
        iriap_send_error(skb, IRIAPE_NO_SUCH_ATTRIBUTE);
        return;
    }

    iriap_send_response(skb, IRIAPOK_SUCCESS, obj->attribute_value, strlen(obj->attribute_value));
}

void iriap_get_attr_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    char *class_name = NULL, *attr_name = NULL;
    int class_len, attr_len;
    struct iriap_object *obj;
    struct iriap_attribute *attr;
    int err = 0;

    IRDA_DEBUG(2, "%s()\n", __func__);

    if (!skb) {
        IRDA_DEBUG(0, "%s(), no skb!\n", __func__);
        return;
    }

    class_name = skb->data;
    class_len = strlen(class_name);
    if (class_len >= IRIAP_MAX_CLASS_NAME) {
        IRDA_DEBUG(0, "%s(), class name too long\n", __func__);
        iriap_send_error(self, skb, IRIAP_ECLASSNOTFOUND);
        return;
    }

    attr_name = class_name + class_len + 1;
    attr_len = strlen(attr_name);
    if (attr_len >= IRIAP_MAX_ATTR_NAME) {
        IRDA_DEBUG(0, "%s(), attribute name too long\n", __func__);
        iriap_send_error(self, skb, IRIAP_EATTRNOTFOUND);
        return;
    }

    obj = iriap_find_object(self, class_name);
    if (!obj) {
        IRDA_DEBUG(0, "%s(), object not found\n", __func__);
        iriap_send_error(self, skb, IRIAP_ECLASSNOTFOUND);
        return;
    }

    attr = iriap_find_attribute(obj, attr_name);
    if (!attr) {
        IRDA_DEBUG(0, "%s(), attribute not found\n", __func__);
        iriap_send_error(self, skb, IRIAP_EATTRNOTFOUND);
        return;
    }

    IRDA_DEBUG(2, "%s(), found attribute %s\n", __func__, attr_name);

    err = iriap_send_value(self, skb, attr->value);
    if (err < 0) {
        IRDA_DEBUG(0, "%s(), failed to send value\n", __func__);
        iriap_send_error(self, skb, IRIAP_EUNKNOWN);
    }
}

void iriap_get_attr_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    char *className, *attrName;
    int classNameLen, attrNameLen;
    struct iriap_object *object;
    struct iriap_attribute *attribute;

    if (!self || !skb) {
        IRDA_DEBUG(0, "Invalid input parameters\n");
        return;
    }

    className = skb->data;
    classNameLen = strlen(className);
    if (classNameLen > IRIAP_MAX_CLASS_NAME_LEN) {
        IRDA_DEBUG(0, "Class name too long\n");
        iriap_send_error_response(skb, IRIAP_ERROR_INVALID_CLASS);
        return;
    }

    attrName = className + classNameLen + 1;
    attrNameLen = strlen(attrName);
    if (attrNameLen > IRIAP_MAX_ATTRIBUTE_NAME_LEN) {
        IRDA_DEBUG(0, "Attribute name too long\n");
        iriap_send_error_response(skb, IRIAP_ERROR_INVALID_ATTRIBUTE);
        return;
    }

    object = iriap_find_object_by_name(self, className);
    if (!object) {
        IRDA_DEBUG(0, "Object not found: %s\n", className);
        iriap_send_error_response(skb, IRIAP_ERROR_OBJECT_NOT_FOUND);
        return;
    }

    attribute = iriap_find_attribute_by_name(object, attrName);
    if (!attribute) {
        IRDA_DEBUG(0, "Attribute not found: %s\n", attrName);
        iriap_send_error_response(skb, IRIAP_ERROR_ATTRIBUTE_NOT_FOUND);
        return;
    }

    IRDA_DEBUG(2, "Found attribute: %s with value: %s\n", attrName, attribute->value);
    iriap_send_success_response(skb, attribute->value);
}

void iriap_get_attribute_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    char *className, *attributeName;
    int classNameLength, attributeNameLength;
    struct sk_buff *response;

    if (!self || !skb) {
        IRDA_DEBUG(0, "%s, invalid parameters\n", __func__);
        return;
    }

    className = skb_pull_data(skb, &classNameLength);
    if (!className || classNameLength > IRIA_MAX_NAME_LEN) {
        IRDA_DEBUG(0, "%s, invalid class name length\n", __func__);
        iriap_send_error_response(skb, IRIA_ERR_INVALID_DATA);
        return;
    }

    attributeName = skb_pull_data(skb, &attributeNameLength);
    if (!attributeName || attributeNameLength > IRIA_MAX_NAME_LEN) {
        IRDA_DEBUG(0, "%s, invalid attribute name length\n", __func__);
        iriap_send_error_response(skb, IRIA_ERR_INVALID_DATA);
        return;
    }

    struct iriap_object *obj = iriap_find_object_by_class(self, className);
    if (!obj) {
        IRDA_DEBUG(0, "%s, object not found\n", __func__);
        iriap_send_error_response(skb, IRIA_ERR_NO_SUCH_OBJECT);
        return;
    }

    struct iriap_attribute *attr = iriap_find_attribute(obj, attributeName);
    if (!attr) {
        IRDA_DEBUG(0, "%s, attribute not found\n", __func__);
        iriap_send_error_response(skb, IRIA_ERR_NO_SUCH_ATTRIBUTE);
        return;
    }

    response = iriap_create_response_packet(skb, IRIA_RSP_GET_ATTRIBUTE);
    if (!response) {
        IRDA_DEBUG(0, "%s, failed to create response packet\n", __func__);
        return;
    }

    if (skb_put_data(response, attr->value, attr->valueLength) < 0) {
        IRDA_DEBUG(0, "%s, failed to append attribute value\n", __func__);
        kfree_skb(response);
        return;
    }

    iriap_send_response(self, response);
}
